// /purge command entrypoint. Validate the option values from the interaction
// body, capture interaction info needed for the deferred-reply PATCH, and
// pass through downstream.
const body = $input.first().json.body || $input.first().json;
const opts = body.options || {};

const count = Number(opts.count);
const userId = opts.user || null;
const contains = (opts.contains || '').toString().trim() || null;

const channelId = body.channelId;
const interactionToken = body.interactionToken;
const applicationId = body.applicationId;
const invoker = body.user || {};
const perms = body.permissions || {};

let valid = true;
let errorMsg = '';

// Defense in depth: Discord's setDefaultMemberPermissions hides /purge from
// non-staff in the slash menu, but a forged interaction or a misconfigured
// channel override could still reach this webhook. Reject unless the bridge
// confirmed the invoker has ManageMessages.
if (!perms.canManageMessages) {
  valid = false;
  errorMsg = 'هذا الأمر مخصص للإدارة فقط (يتطلب صلاحية إدارة الرسائل)';
} else if (!Number.isInteger(count) || count < 1 || count > 1000) {
  valid = false;
  errorMsg = 'الرجاء تحديد عدد رسائل بين 1 و 1000';
} else if (!channelId) {
  valid = false;
  errorMsg = 'القناة غير معروفة - تأكد من استخدام الأمر داخل قناة نصية';
} else if (!interactionToken || !applicationId) {
  valid = false;
  errorMsg = 'interaction context مفقود';
}

if (valid && contains && contains.length > 200) {
  valid = false;
  errorMsg = 'فلتر contains طويل جداً (الحد الأقصى 200 حرف)';
}

return [{
  json: {
    valid,
    errorMsg,
    count,
    userId,
    contains,
    channelId,
    interactionToken,
    applicationId,
    invokerId: invoker.id || null,
    invokerName: invoker.displayName || invoker.username || 'unknown',
  },
}];

// Heavy lifter: fetch -> filter -> bulk-delete (<14d) + per-message DELETE
// (>=14d). Uses $helpers.httpRequest with the bot token from $env so the
// individual chunk calls don't each need their own HTTP node.
//
// Hard limits enforced upstream by parse-purge (count 1..1000) so the
// pagination loop is bounded.
const ctx = $input.first().json;
const token = $env.DISCORD_BOT_TOKEN || '';
if (!token) {
  return [{ json: { ...ctx, ok: false, errorMsg: 'DISCORD_BOT_TOKEN غير مضبوط على n8n' } }];
}
const headers = {
  Authorization: `Bot ${token}`,
  'Content-Type': 'application/json',
};

const channelId = ctx.channelId;
const wantCount = ctx.count;
const userFilter = ctx.userId;
const containsFilter = ctx.contains ? ctx.contains.toLowerCase() : null;

const FOURTEEN_DAYS_MS = 14 * 24 * 60 * 60 * 1000;
const now = Date.now();

// Step 1: paginated GET of recent messages until we have `wantCount`
// matching the filters or Discord returns < 100 (channel exhausted).
const matched = [];
let before = null;
let safetyHops = 0;
let scannedMessages = 0;
const MAX_HOPS = 20; // 20 pages * 100 = 2000 messages scanned max

while (matched.length < wantCount && safetyHops < MAX_HOPS) {
  safetyHops += 1;
  const url = new URL(`https://discord.com/api/v10/channels/${channelId}/messages`);
  url.searchParams.set('limit', '100');
  if (before) url.searchParams.set('before', before);
  let page;
  try {
    page = await $helpers.httpRequest({
      method: 'GET',
      url: url.toString(),
      headers,
      json: true,
    });
  } catch (err) {
    return [{ json: { ...ctx, ok: false, errorMsg: `فشل في قراءة الرسائل: ${err.message || err}` } }];
  }
  if (!Array.isArray(page) || page.length === 0) break;
  scannedMessages += page.length;

  for (const m of page) {
    if (matched.length >= wantCount) break;
    if (userFilter && m.author?.id !== userFilter) continue;
    if (containsFilter && !(m.content || '').toLowerCase().includes(containsFilter)) continue;
    matched.push(m);
  }

  if (page.length < 100) break;
  before = page[page.length - 1].id;
}

// Step 2: split by age. Discord rejects bulk-delete for messages older
// than 14 days, so those get individual DELETE calls instead.
const recent = [];
const old = [];
for (const m of matched) {
  const ts = m.timestamp ? Date.parse(m.timestamp) : 0;
  if (ts && (now - ts) < FOURTEEN_DAYS_MS) recent.push(m.id);
  else old.push(m.id);
}

let bulkDeleted = 0;
let individualDeleted = 0;
let failed = 0;

// Step 3: bulk-delete chunks of up to 100, but only if 2+ messages. Discord
// rejects bulk-delete payloads of size 1, so route singletons to per-msg.
const bulkChunks = [];
let buf = [];
for (const id of recent) {
  buf.push(id);
  if (buf.length === 100) { bulkChunks.push(buf); buf = []; }
}
if (buf.length >= 2) bulkChunks.push(buf);
else if (buf.length === 1) old.push(buf[0]);

for (const chunk of bulkChunks) {
  try {
    await $helpers.httpRequest({
      method: 'POST',
      url: `https://discord.com/api/v10/channels/${channelId}/messages/bulk-delete`,
      headers,
      body: { messages: chunk },
      json: true,
    });
    bulkDeleted += chunk.length;
  } catch (err) {
    failed += chunk.length;
  }
}

// Step 4: individual DELETE for the >= 14d (or singleton) list.
for (const id of old) {
  try {
    await $helpers.httpRequest({
      method: 'DELETE',
      url: `https://discord.com/api/v10/channels/${channelId}/messages/${id}`,
      headers,
    });
    individualDeleted += 1;
  } catch (err) {
    failed += 1;
  }
}

return [{
  json: {
    ...ctx,
    ok: true,
    scannedPages: safetyHops,
    scannedMessages,
    matchedCount: matched.length,
    bulkDeleted,
    individualDeleted,
    failed,
    totalDeleted: bulkDeleted + individualDeleted,
  },
}];

