={{ JSON.stringify({
  "content": `✅ تم مسح **${$json.totalDeleted}** رسالة` +
    ($json.individualDeleted > 0 ? `\n• ${$json.bulkDeleted} عبر bulk-delete + ${$json.individualDeleted} مسح فردي` : '') +
